// Parse incoming lab results email/data
const emailBody = $input.first().json.text || $input.first().json.body || '';
const subject = $input.first().json.subject || '';

console.log('📋 Processing lab results for {{CLINIC_NAME}}');

// Enhanced parsing logic for various lab result formats
let patientId = 'UNKNOWN';
let petName = 'UNKNOWN';
let ownerName = 'UNKNOWN';
let resultStatus = 'UNKNOWN';
let testName = 'UNKNOWN';
let resultValue = 'UNKNOWN';
let labName = 'UNKNOWN';
let testDate = new Date().toISOString().split('T')[0];
let urgencyLevel = 'Normal';

// Try multiple parsing patterns for different lab formats
const patterns = {
  patientId: [
    /Patient\s*(?:ID|#)?:?\s*([A-Za-z0-9-]+)/i,
    /ID\s*(?:Number|#)?:?\s*([A-Za-z0-9-]+)/i,
    /Chart\s*(?:Number|#)?:?\s*([A-Za-z0-9-]+)/i
  ],
  petName: [
    /Pet\s*(?:Name)?:?\s*([^\n\r,]+)/i,
    /Animal\s*(?:Name)?:?\s*([^\n\r,]+)/i,
    /Patient\s*(?:Name)?:?\s*([^\n\r,]+)/i
  ],
  ownerName: [
    /Owner\s*(?:Name)?:?\s*([^\n\r,]+)/i,
    /Client\s*(?:Name)?:?\s*([^\n\r,]+)/i,
    /Guardian\s*(?:Name)?:?\s*([^\n\r,]+)/i
  ],
  resultStatus: [
    /(?:Result\s*)?Status:?\s*(Normal|Abnormal|Critical|Pending|Urgent)/i,
    /Results?:?\s*(Normal|Abnormal|Critical|Pending|Urgent)/i
  ],
  testName: [
    /Test\s*(?:Name|Type)?:?\s*([^\n\r,]+)/i,
    /Procedure:?\s*([^\n\r,]+)/i,
    /Analysis:?\s*([^\n\r,]+)/i
  ],
  resultValue: [
    /(?:Result\s*)?Value:?\s*([^\n\r,]+)/i,
    /Finding:?\s*([^\n\r,]+)/i,
    /Measurement:?\s*([^\n\r,]+)/i
  ],
  labName: [
    /Lab(?:oratory)?\s*(?:Name)?:?\s*([^\n\r,]+)/i,
    /Facility:?\s*([^\n\r,]+)/i
  ],
  testDate: [
    /(?:Test\s*|Sample\s*)?Date:?\s*(\d{1,2}[\/-]\d{1,2}[\/-]\d{2,4})/i,
    /Collected:?\s*(\d{1,2}[\/-]\d{1,2}[\/-]\d{2,4})/i
  ]
};

// Apply patterns to extract data
for (const [field, patternList] of Object.entries(patterns)) {
  for (const pattern of patternList) {
    const match = emailBody.match(pattern);
    if (match && match[1]) {
      if (field === 'patientId') patientId = match[1].trim();
      else if (field === 'petName') petName = match[1].trim();
      else if (field === 'ownerName') ownerName = match[1].trim();
      else if (field === 'resultStatus') resultStatus = match[1].trim();
      else if (field === 'testName') testName = match[1].trim();
      else if (field === 'resultValue') resultValue = match[1].trim();
      else if (field === 'labName') labName = match[1].trim();
      else if (field === 'testDate') testDate = match[1].trim();
      break;
    }
  }
}

// Check for urgency indicators
if (/(?:urgent|critical|immediate|stat|emergency)/i.test(emailBody) || 
    /(?:urgent|critical|immediate|stat|emergency)/i.test(subject)) {
  urgencyLevel = 'URGENT';
} else if (/(?:abnormal|elevated|low|high|outside)/i.test(emailBody)) {
  urgencyLevel = 'Attention';
}

// Generate formatted report
const formattedResults = {
  patientId,
  petName,
  ownerName,
  testName,
  resultValue,
  resultStatus,
  labName,
  testDate,
  urgencyLevel,
  receivedTimestamp: new Date().toISOString(),
  rawEmailBody: emailBody,
  emailSubject: subject,
  clinicName: '{{CLINIC_NAME}}'
};

console.log(`📊 Lab result parsed:`);
console.log(`   - Patient: ${petName} (ID: ${patientId})`);
console.log(`   - Owner: ${ownerName}`);
console.log(`   - Test: ${testName}`);
console.log(`   - Status: ${resultStatus} (${urgencyLevel})`);

return [{ json: formattedResults }];

